/// Compatibility projection for fixed-point arithmetic oracles that need only
/// the exact iteration count. The optimizer discards the presentation field.
pub fn escape<const L: usize>(
    _ cx_s: u32, _ cx: Limbs<L>, _ cy_s: u32, _ cy: Limbs<L>, _ max_iter: i32,
) -> i32
    where Limbs<L>: TruncRows<Limbs<L>> + Mac + ShiftAppend + Head + Carry
                  + Zero + SubBorrow + Select + Top + OrLower + UpperFraction
                  + Copy,
{
    escape_sample<L>(cx_s, cx, cy_s, cy, max_iter).iterations
}

