impl Default for Last {
    fn default() -> Self {
        Last { value: 0.0 }
    }
}

impl<T: Default> Default for More<T> {
    fn default() -> Self {
        More {
            lead: 0.0,
            tail: T::default(),
        }
    }
}

impl Eq for Last {
    fn eq(self, _ other: Self) -> bool {
        self.value == other.value
    }
}

impl<T: Eq> Eq for More<T> {
    fn eq(self, _ other: Self) -> bool {
        self.lead == other.lead && self.tail == other.tail
    }
}

