/// Lower terms decide comparisons when the leading terms are equal.
impl Ord for Last {
    fn lt(self, _ other: Self) -> bool { self.value < other.value }
    fn le(self, _ other: Self) -> bool { self.value <= other.value }
    fn gt(self, _ other: Self) -> bool { self.value > other.value }
    fn ge(self, _ other: Self) -> bool { self.value >= other.value }
}

impl<T: Ord> Ord for More<T> {
    fn lt(self, _ other: Self) -> bool {
        self.lead < other.lead || (self.lead == other.lead && self.tail < other.tail)
    }
    fn le(self, _ other: Self) -> bool {
        self.lead < other.lead || (self.lead == other.lead && self.tail <= other.tail)
    }
    fn gt(self, _ other: Self) -> bool {
        self.lead > other.lead || (self.lead == other.lead && self.tail > other.tail)
    }
    fn ge(self, _ other: Self) -> bool {
        self.lead > other.lead || (self.lead == other.lead && self.tail >= other.tail)
    }
}

impl Add for Last {
    fn add(own self, _ other: own Self) -> Self {
        self.add_corr(other, 0.0)
    }
}

impl<T: Exp + Copy> Add for More<T> {
    fn add(own self, _ other: own Self) -> Self {
        self.add_corr(other, 0.0)
    }
}

impl Sub for Last {
    fn sub(own self, _ other: own Self) -> Self {
        self.add_corr(other.negate(), 0.0)
    }
}

impl<T: Exp + Copy> Sub for More<T> {
    fn sub(own self, _ other: own Self) -> Self {
        self.add_corr(other.negate(), 0.0)
    }
}

/// `Expansion<N>`: N=1 is `Last` (a bare f32); N>=2 is `More` over
