struct FieldCosetLde<const N: usize, F> {
    valid: bool,
    evaluations: [F; N],
}

impl<const N: usize, F: Copy> Copy for FieldCosetLde<N, F> {}

pub fn write_radix2_coset_lde<
    const N: usize,
    const OUT: usize,
    F: Radix2Field,
>(
    _ base_evaluations: ref [F; N],
    _ shift: F,
    _ evaluations: mut [F; OUT],
) -> bool
    where
        N > 0,
        { (N & (N - 1)) == 0 },
        { radix2_field_domain_supported<N, F>() },
        OUT > 0,
        OUT > N,
        { (OUT & (OUT - 1)) == 0 },
        { radix2_field_domain_supported<OUT, F>() },
        { (OUT % N) == 0 },
{
    let zero = F::radix2_zero()
    let one = F::radix2_root(0)
    evaluations = [zero; OUT]
    if shift.radix2_is_zero()
        || shift.radix2_pow(OUT.downcast_truncate()).radix2_sub(one).radix2_is_zero()
    {
        return false
    }

    let mut coefficients = [zero; N]
    let mut index: usize = 0
    while index < N {
        coefficients[index] = base_evaluations[index]
        index = index + 1
    }
    radix2_intt_in_place<N, F>(mut coefficients)
    let mut shift_power = one
    index = 0
    while index < N {
        evaluations[index] = coefficients[index].radix2_mul(shift_power)
        shift_power = shift_power.radix2_mul(shift)
        index = index + 1
    }
    radix2_ntt_in_place<OUT, F>(mut evaluations)
    true
}

fn radix2_field_coset_lde<const N: usize, const OUT: usize, F: Radix2Field>(
    _ base_evaluations: own [F; N],
    _ shift: F,
) -> FieldCosetLde<OUT, F>
    where
        N > 0,
        { (N & (N - 1)) == 0 },
        { radix2_field_domain_supported<N, F>() },
        OUT > 0,
        OUT > N,
        { (OUT & (OUT - 1)) == 0 },
        { radix2_field_domain_supported<OUT, F>() },
        { (OUT % N) == 0 },
{
    let mut evaluations = [F::radix2_zero(); OUT]
    let valid = write_radix2_coset_lde<N, OUT, F>(
        ref base_evaluations,
        shift,
        mut evaluations,
    )
    FieldCosetLde {
        valid: valid,
        evaluations: evaluations,
    }
}

/// A low-degree extension plus the proof that its evaluation coset is
/// disjoint from the base trace subgroup. Invalid shifts fail closed with an
/// all-zero evaluation vector and `valid = false`.
pub struct Radix2CosetLde<const N: usize, const L: usize, M> {
    pub valid: bool,
    pub evaluations: [FieldElement<L, M>; N],
}

impl<const N: usize, const L: usize, M> Copy for Radix2CosetLde<N, L, M> {}

pub fn radix2_coset_lde<
    const N: usize,
    const OUT: usize,
    const L: usize,
    M,
>(
    _ base_evaluations: own [FieldElement<L, M>; N],
    _ shift: FieldElement<L, M>,
) -> Radix2CosetLde<OUT, L, M>
    where
        N > 0,
        { (N & (N - 1)) == 0 },
        { radix2_log_unchecked<N>() <= M::TWO_ADICITY },
        { radix2_field_domain_supported<N, FieldElement<L, M>>() },
        OUT > 0,
        OUT > N,
        { (OUT & (OUT - 1)) == 0 },
        { radix2_log_unchecked<OUT>() <= M::TWO_ADICITY },
        { radix2_field_domain_supported<OUT, FieldElement<L, M>>() },
        { (OUT % N) == 0 },
        L >= 3,
        M: TwoAdicModulus<L> + U32EmbeddingModulus<L>,
        Limbs<L>: Head + ShiftAppend + Copy,
{
    let lde = radix2_field_coset_lde<N, OUT, FieldElement<L, M>>(
        base_evaluations,
        shift,
    )
    Radix2CosetLde {
        valid: lde.valid,
        evaluations: lde.evaluations,
    }
}

