/// Numerators grouped by the four zerofiers shared by transition AIRs.
/// Constraint systems produce this field-neutral record; scalar, packed, and
/// GPU interpreters all apply the same quotient formula below.
pub struct AirConstraintNumerators<F: Radix2Field> {
    pub all_rows: F,
    pub pair_rows: F,
    pub first_row: F,
    pub last_row: F,
}

pub struct AirCompositionValue<F: Radix2Field> {
    pub valid: bool,
    pub value: F,
}

/// Divide four constraint families by the trace, transition, initial, and
/// terminal zerofiers. The trace size remains a type-level fact, so backends
/// may change placement without receiving a second composition formula.
pub fn air_composition_value<F: Radix2Field, const N: usize>(
    _ point: F,
    _ numerators: AirConstraintNumerators<F>,
) -> AirCompositionValue<F>
where
    N > 0,
    N > 1,
    { (N & (N - 1)) == 0 },
{
    let one = F::radix2_root(0)
    let last_trace_point = F::radix2_root(radix2_log<N>())
        .radix2_inverse_or_zero()
    let trace_zerofier = point.radix2_pow(N.downcast_truncate())
        .radix2_sub(one)
    let first_zerofier = point.radix2_sub(one)
    let last_zerofier = point.radix2_sub(last_trace_point)
    if trace_zerofier.radix2_is_zero()
        || first_zerofier.radix2_is_zero()
        || last_zerofier.radix2_is_zero() {
        return AirCompositionValue {
            valid: false,
            value: F::radix2_zero(),
        }
    }
    let trace_inverse = trace_zerofier.radix2_inverse_or_zero()
    AirCompositionValue {
        valid: true,
        value: numerators.all_rows.radix2_mul(trace_inverse).radix2_add(
            numerators.pair_rows
                .radix2_mul(last_zerofier)
                .radix2_mul(trace_inverse),
        ).radix2_add(
            numerators.first_row
                .radix2_mul(first_zerofier.radix2_inverse_or_zero()),
        ).radix2_add(
            numerators.last_row
                .radix2_mul(last_zerofier.radix2_inverse_or_zero()),
        ),
    }
}

